[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --primary-dark: #171717;
      --accent-blue: #0072F5;
      --accent-blue-hover: #005BBF;
      --background-light: #FAFAFA;
      --background-white: #FFFFFF;
      --gray-50: #F5F5F5;
      --gray-100: #E5E5E5;
      --gray-200: #CCCCCC;
      --gray-300: #B3B3B3;
      --gray-400: #8C8C8C;
      --gray-500: #666666;
      --gray-600: #4D4D4D;
      --text-secondary: #525252;
      --border-color: #E5E5E5;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1);
      --radius-sm: 6px;
      --radius-md: 8px;
      --radius-lg: 12px;
      --radius-full: 9999px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: var(--background-light);
      color: var(--primary-dark);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    /* Header */
    .header {
      background: var(--background-white);
      border-bottom: 1px solid var(--border-color);
      position: sticky;
      top: 0;
      z-index: 100;
    }

    .header-inner {
      max-width: 1400px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      font-weight: 800;
      font-size: 20px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--accent-blue);
      border-radius: 6px;
    }

    .nav-main {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-link {
      padding: 8px 12px;
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-500);
      border-radius: var(--radius-sm);
      transition: all 0.15s ease;
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .nav-link:hover {
      color: var(--primary-dark);
      background: var(--gray-50);
    }

    .nav-link.active {
      color: var(--primary-dark);
    }

    .nav-dropdown-trigger {
      position: relative;
    }

    .dropdown-icon {
      width: 12px;
      height: 12px;
      transition: transform 0.2s;
    }

    .nav-link:hover .dropdown-icon,
    .nav-dropdown-trigger.open .dropdown-icon {
      transform: rotate(180deg);
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--background-white);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      min-width: 600px;
      opacity: 0;
      visibility: hidden;
      transition: all 0.2s ease;
      margin-top: 8px;
    }

    .mega-menu.open {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu-inner {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .mega-menu-section h4 {
      font-size: 12px;
      font-weight: 600;
      color: var(--gray-400);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 12px;
    }

    .mega-menu-items {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mega-menu-item {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding: 8px;
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .mega-menu-item:hover {
      background: var(--gray-50);
    }

    .mega-menu-item-icon {
      width: 32px;
      height: 32px;
      background: var(--gray-50);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      flex-shrink: 0;
    }

    .mega-menu-item-text {
      display: flex;
      flex-direction: column;
    }

    .mega-menu-item-title {
      font-size: 14px;
      font-weight: 500;
      color: var(--primary-dark);
    }

    .mega-menu-item-desc {
      font-size: 12px;
      color: var(--gray-500);
    }

    /* Header Actions */
    .header-actions {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn {
      padding: 8px 16px;
      font-size: 14px;
      font-weight: 500;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }

    .btn-ghost {
      color: var(--gray-500);
    }

    .btn-ghost:hover {
      color: var(--primary-dark);
      background: var(--gray-50);
    }

    .btn-primary {
      background: var(--accent-blue);
      color: white;
    }

    .btn-primary:hover {
      background: var(--accent-blue-hover);
    }

    /* Search Bar */
    .search-container {
      max-width: 1400px;
      margin: 0 auto;
      padding: 24px 24px 0;
    }

    .search-input-wrapper {
      position: relative;
      max-width: 400px;
    }

    .search-icon {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 18px;
      height: 18px;
      color: var(--gray-400);
    }

    .search-input {
      width: 100%;
      padding: 10px 12px 10px 40px;
      font-size: 14px;
      border: 1px solid var(--border-color);
      border-radius: var(--radius-full);
      background: var(--background-white);
      transition: all 0.15s;
    }

    .search-input:focus {
      outline: none;
      border-color: var(--accent-blue);
      box-shadow: 0 0 0 3px rgba(0, 114, 245, 0.1);
    }

    .search-input::placeholder {
      color: var(--gray-400);
    }

    /* Category Filters */
    .filters-container {
      max-width: 1400px;
      margin: 0 auto;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 12px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }

    .filters-container::-webkit-scrollbar {
      display: none;
    }

    .filter-pill {
      padding: 8px 16px;
      font-size: 14px;
      font-weight: 500;
      border-radius: var(--radius-full);
      border: 1px solid var(--border-color);
      background: var(--background-white);
      color: var(--gray-500);
      white-space: nowrap;
      transition: all 0.15s;
    }

    .filter-pill:hover {
      border-color: var(--gray-300);
      color: var(--primary-dark);
    }

    .filter-pill.active {
      background: var(--primary-dark);
      color: white;
      border-color: var(--primary-dark);
    }

    /* Main Content */
    .main-content {
      max-width: 1400px;
      margin: 0 auto;
      padding: 0 24px 48px;
    }

    /* Featured Articles */
    .featured-section {
      padding: 48px 0;
      border-bottom: 1px solid var(--border-color);
    }

    .section-label {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 16px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .featured-card {
      background: var(--background-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-color);
      overflow: hidden;
      transition: all 0.2s;
    }

    .featured-card:hover {
      border-color: var(--gray-300);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .featured-card-main {
      grid-column: span 2;
    }

    .featured-card-image {
      height: 200px;
      background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-50) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .featured-card-main .featured-card-image {
      height: 280px;
    }

    .featured-card-icon {
      font-size: 48px;
      opacity: 0.5;
    }

    .featured-card-content {
      padding: 24px;
    }

    .featured-card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 12px;
    }

    .category-tag {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-blue);
      background: rgba(0, 114, 245, 0.1);
      padding: 4px 8px;
      border-radius: var(--radius-sm);
    }

    .featured-card-main .category-tag {
      padding: 6px 12px;
      font-size: 13px;
    }

    .post-date {
      font-size: 13px;
      color: var(--gray-400);
    }

    .featured-card-title {
      font-size: 20px;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
    }

    .featured-card-main .featured-card-title {
      font-size: 28px;
    }

    .featured-card-excerpt {
      font-size: 15px;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-bottom: 16px;
    }

    .featured-card-main .featured-card-excerpt {
      font-size: 16px;
    }

    .author-info {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .author-avatar {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent-blue) 0%, #00B4D8 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 600;
      font-size: 14px;
    }

    .author-name {
      font-size: 14px;
      font-weight: 500;
    }

    /* Agentic Stats */
    .agentic-stats {
      display: flex;
      flex-wrap: wrap;
      gap: 24px;
      margin-top: 24px;
      padding-top: 24px;
      border-top: 1px solid var(--border-color);
    }

    .stat-item {
      flex: 1;
      min-width: 180px;
    }

    .stat-value {
      font-size: 32px;
      font-weight: 800;
      color: var(--accent-blue);
      line-height: 1;
    }

    .stat-label {
      font-size: 14px;
      color: var(--gray-500);
      margin-top: 4px;
    }

    /* Latest News */
    .latest-section {
      padding: 48px 0;
    }

    .latest-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .latest-card {
      background: var(--background-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-color);
      padding: 24px;
      transition: all 0.2s;
      display: flex;
      flex-direction: column;
    }

    .latest-card:hover {
      border-color: var(--gray-300);
      box-shadow: var(--shadow-sm);
    }

    .latest-card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 12px;
    }

    .latest-card-title {
      font-size: 17px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 8px;
      flex-grow: 1;
    }

    .latest-card-excerpt {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.5;
      margin-bottom: 16px;
    }

    .latest-card-footer {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: auto;
    }

    .latest-card .author-avatar {
      width: 28px;
      height: 28px;
      font-size: 12px;
    }

    .latest-card .author-name {
      font-size: 13px;
    }

    /* No Results */
    .no-results {
      display: none;
      grid-column: 1 / -1;
      text-align: center;
      padding: 64px 24px;
      background: var(--background-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-color);
    }

    .no-results.visible {
      display: block;
    }

    .no-results-icon {
      width: 48px;
      height: 48px;
      color: var(--gray-300);
      margin: 0 auto 16px;
    }

    .no-results-title {
      font-size: 18px;
      font-weight: 600;
      margin-bottom: 8px;
    }

    .no-results-text {
      font-size: 14px;
      color: var(--gray-500);
    }

    /* Show More */
    .show-more-container {
      display: flex;
      justify-content: center;
      padding: 32px 0;
    }

    .btn-show-more {
      padding: 12px 32px;
      font-size: 15px;
      font-weight: 500;
      border-radius: var(--radius-full);
      border: 1px solid var(--border-color);
      background: var(--background-white);
      color: var(--primary-dark);
      transition: all 0.15s;
    }

    .btn-show-more:hover {
      border-color: var(--gray-300);
      box-shadow: var(--shadow-sm);
    }

    .btn-show-more:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    /* CTA Banner */
    .cta-banner {
      background: var(--primary-dark);
      border-radius: var(--radius-lg);
      padding: 48px;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 32px;
      margin: 48px 0;
    }

    .cta-content {
      flex: 1;
      min-width: 300px;
    }

    .cta-title {
      font-size: 28px;
      font-weight: 700;
      color: white;
      margin-bottom: 12px;
    }

    .cta-text {
      font-size: 16px;
      color: rgba(255,255,255,0.7);
    }

    .cta-buttons {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn-cta-primary {
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 600;
      background: white;
      color: var(--primary-dark);
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }

    .btn-cta-primary:hover {
      background: var(--gray-100);
    }

    .btn-cta-secondary {
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 500;
      border: 1px solid rgba(255,255,255,0.3);
      color: white;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }

    .btn-cta-secondary:hover {
      border-color: rgba(255,255,255,0.5);
      background: rgba(255,255,255,0.1);
    }

    /* Footer */
    .footer {
      background: var(--background-white);
      border-top: 1px solid var(--border-color);
      padding: 64px 24px 32px;
    }

    .footer-inner {
      max-width: 1400px;
      margin: 0 auto;
    }

    .footer-main {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      color: var(--primary-dark);
      margin-bottom: 16px;
    }

    .footer-links {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-link {
      font-size: 14px;
      color: var(--gray-500);
      transition: color 0.15s;
    }

    .footer-link:hover {
      color: var(--primary-dark);
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid var(--border-color);
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-brand {
      font-size: 14px;
      color: var(--gray-500);
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 14px;
      color: var(--gray-500);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22C55E;
      border-radius: 50%;
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .social-link {
      width: 36px;
      height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: var(--radius-sm);
      color: var(--gray-400);
      transition: all 0.15s;
    }

    .social-link:hover {
      background: var(--gray-50);
      color: var(--primary-dark);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .featured-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .featured-card-main {
        grid-column: span 2;
      }

      .latest-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-main {
        grid-template-columns: repeat(3, 1fr);
      }

      .mega-menu {
        min-width: 500px;
      }
    }

    @media (max-width: 768px) {
      .header-inner {
        padding: 0 16px;
      }

      .nav-main {
        display: none;
      }

      .header-actions .btn-ghost {
        display: none;
      }

      .search-container {
        padding: 16px 16px 0;
      }

      .filters-container {
        padding: 16px;
        gap: 8px;
      }

      .filter-pill {
        padding: 6px 12px;
        font-size: 13px;
      }

      .main-content {
        padding: 0 16px 32px;
      }

      .featured-section,
      .latest-section {
        padding: 32px 0;
      }

      .featured-grid {
        grid-template-columns: 1fr;
      }

      .featured-card-main {
        grid-column: span 1;
      }

      .featured-card-title {
        font-size: 18px;
      }

      .featured-card-main .featured-card-title {
        font-size: 22px;
      }

      .featured-card-main .featured-card-image {
        height: 200px;
      }

      .agentic-stats {
        gap: 16px;
      }

      .stat-item {
        min-width: 140px;
      }

      .stat-value {
        font-size: 24px;
      }

      .latest-grid {
        grid-template-columns: 1fr;
      }

      .cta-banner {
        padding: 32px 24px;
        flex-direction: column;
        text-align: center;
      }

      .cta-title {
        font-size: 22px;
      }

      .cta-buttons {
        justify-content: center;
      }

      .footer-main {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .header-actions {
        gap: 4px;
      }

      .btn {
        padding: 8px 12px;
        font-size: 13px;
      }

      .btn-primary {
        padding: 8px 12px;
      }

      .footer-main {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
