  <script>
    // Category Filter Toggle
    const filterPills = document.querySelectorAll('.filter-pill');
    const latestCards = document.querySelectorAll('.latest-card');
    const featuredCards = document.querySelectorAll('.featured-card');
    const noResults = document.getElementById('no-results');
    const searchInput = document.getElementById('search-input');

    let activeCategory = 'all';
    let searchQuery = '';

    function filterPosts() {
      let visibleCount = 0;

      latestCards.forEach(card => {
        const cardCategory = card.dataset.category;
        const cardSearch = (card.dataset.search || '').toLowerCase();
        const cardTitle = card.querySelector('.latest-card-title').textContent.toLowerCase();
        const cardExcerpt = card.querySelector('.latest-card-excerpt').textContent.toLowerCase();
        const searchText = (searchQuery + ' ' + cardTitle + ' ' + cardExcerpt + ' ' + cardSearch).toLowerCase();

        const matchesCategory = activeCategory === 'all' || cardCategory === activeCategory;
        const matchesSearch = searchQuery === '' || searchText.includes(searchQuery);

        if (matchesCategory && matchesSearch) {
          card.style.display = 'flex';
          visibleCount++;
        } else {
          card.style.display = 'none';
        }
      });

      featuredCards.forEach(card => {
        const cardCategory = card.dataset.category;
        const cardSearch = (card.dataset.search || '').toLowerCase();
        const cardTitle = card.querySelector('.featured-card-title').textContent.toLowerCase();
        const cardExcerpt = card.querySelector('.featured-card-excerpt')?.textContent.toLowerCase() || '';
        const searchText = (searchQuery + ' ' + cardTitle + ' ' + cardExcerpt + ' ' + cardSearch).toLowerCase();

        const matchesCategory = activeCategory === 'all' || cardCategory === activeCategory;
        const matchesSearch = searchQuery === '' || searchText.includes(searchQuery);

        if (matchesCategory && matchesSearch) {
          card.style.display = '';
        } else {
          card.style.display = 'none';
        }
      });

      noResults.classList.toggle('visible', visibleCount === 0);
      document.querySelector('.show-more-container').style.display = visibleCount === 0 ? 'none' : 'flex';
    }

    filterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        filterPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        activeCategory = pill.dataset.category;
        filterPosts();
      });
    });

    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value.trim().toLowerCase();
      filterPosts();
    });

    // Show More Posts
    const showMoreBtn = document.getElementById('show-more-btn');
    const hiddenCards = document.querySelectorAll('.hidden-extra');
    let showingExtra = false;

    showMoreBtn.addEventListener('click', () => {
      if (!showingExtra) {
        hiddenCards.forEach(card => {
          card.style.display = 'flex';
        });
        showingExtra = true;
        showMoreBtn.textContent = 'Show less posts';
      } else {
        hiddenCards.forEach(card => {
          card.style.display = 'none';
        });
        showingExtra = false;
        showMoreBtn.textContent = 'Show more posts';
      }
    });

    // Mega Menu Dropdowns
    const dropdownTriggers = document.querySelectorAll('.nav-dropdown-trigger');

    dropdownTriggers.forEach(trigger => {
      const menu = trigger.querySelector('.mega-menu');

      trigger.addEventListener('mouseenter', () => {
        menu.classList.add('open');
        trigger.classList.add('open');
      });

      trigger.addEventListener('mouseleave', () => {
        menu.classList.remove('open');
        trigger.classList.remove('open');
      });
    });

    // Close mega menus when clicking outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav-dropdown-trigger')) {
        document.querySelectorAll('.mega-menu').forEach(menu => {
          menu.classList.remove('open');
        });
        document.querySelectorAll('.nav-dropdown-trigger').forEach(trigger => {
          trigger.classList.remove('open');
        });
      }
    });
  </script>
</body>
